@import '../../styles/control-elevation.css';

:host {
  display: block;
  position: relative;
  width: 100%;
  height: 100%;
  min-height: 0;
  box-sizing: border-box;
  -webkit-user-select: none;
  user-select: none;
}

.conversation-list {
  position: relative;
  display: flex;
  flex-direction: column;
  width: 100%;
  height: 100%;
  min-height: 0;
  box-sizing: border-box;
}

.conversation-list__viewport {
  position: relative;
  flex: 1 1 auto;
  min-height: 0;
  overflow: auto;
  box-sizing: border-box;
}

.conversation-list__content {
  position: relative;
  min-height: 100%;
  padding: var(--dimension-space-100);
  box-sizing: border-box;
}

.conversation-list__empty {
  position: absolute;
  inset: 0;
  box-sizing: border-box;
}

/* The named slot itself keeps this wrapper from matching :empty. Only create
   its full-size hit area when assigned empty-state content is actually here. */
.conversation-list__empty:not(:has([slot='empty'])) {
  display: none;
}

/* Corner action. Rows scroll beneath it — there is no reserved clearance and no
   fade, so the list keeps its full height whether or not an action is slotted. */
.conversation-list__actions {
  position: absolute;
  right: 0;
  bottom: 0;
  z-index: var(--dimension-z-index-floating);
  padding: 0 var(--dimension-space-200) var(--dimension-space-200) 0;
}

.conversation-list__actions-surface {
  display: flex;
  border-radius: var(--dimension-radius-half);
}

.conversation-list__actions-surface:empty {
  display: none;
}

import { Component, Element, h, Host } from '@stencil/core';

@Component({
  tag: 'ds-conversation-list',
  styleUrl: 'ConversationList.css',
  scoped: true,
})
export class ConversationList {
  @Element() el!: HTMLElement;

  private empty?: HTMLElement;
  private emptySlotObserver?: MutationObserver;

  componentDidLoad(): void {
    this.syncEmptyStateLayout();
    this.emptySlotObserver = new MutationObserver(this.syncEmptyStateLayout);
    this.emptySlotObserver.observe(this.el, { childList: true, subtree: true });
  }

  disconnectedCallback(): void {
    this.emptySlotObserver?.disconnect();
  }

  private syncEmptyStateLayout = (): void => {
    const emptyState = this.el.querySelector<HTMLElement>('[slot="empty"]');
    if (emptyState && !this.empty?.contains(emptyState)) {
      // Stencil's scoped-slot runtime does not relocate nodes appended after
      // hydration. Keep that dynamic fallback aligned with the CSS-owned
      // wrapper used by declarative slot content.
      emptyState.style.setProperty('position', 'absolute');
      emptyState.style.setProperty('inset-block-start', '0');
      emptyState.style.setProperty('inset-inline', '0');
      emptyState.style.setProperty('inset-block-end', '0');
      emptyState.style.setProperty('height', 'auto');
      emptyState.style.setProperty('box-sizing', 'border-box');
    }
  };

  render() {
    return (
      <Host>
        <div class="conversation-list">
          <div class="conversation-list__viewport">
            <div class="conversation-list__content">
              <slot />
              <div
                class="conversation-list__empty"
                ref={element => {
                  this.empty = element;
                }}
              >
                <slot name="empty" />
              </div>
            </div>
          </div>
          <div class="conversation-list__actions">
            <div class="conversation-list__actions-surface ds-control-elevation ds-control-elevation--md ds-control-elevation--press-scale">
              <slot name="actions" />
            </div>
          </div>
        </div>
      </Host>
    );
  }
}
